2: import { getEnvBaseUrl, getApiPrefix } from '@/utils'
3: import { stringifyQuery } from './tools/queryString'
4: 
5: // 请求基准地址
6: const baseUrl = getEnvBaseUrl()
7: 
8: // 拦截器配置
9: const httpInterceptor = {
10:   // 拦截前触发
11:   invoke(options: CustomRequestOptions) {
12:     // 接口请求支持通过 query 参数配置 queryString
13:     if (options.query) {
14:       const queryStr = stringifyQuery({...options.query, interfaceVersion: 19000101})
15:       if (options.url.includes('?')) {
16:         options.url += `&${queryStr}`
17:       }
18:       else {
19:         options.url += `?${queryStr}`
20:       }
21:     }
22:     if (options.data) {
23:       options.data.interfaceVersion = 19000101
24:     }
25:     // 非 http 开头需拼接地址
26:     if (!options.url.startsWith('http')) {
27:       // #ifdef H5
28:       if (JSON.parse(import.meta.env.VITE_APP_PROXY_ENABLE)) {
29:         // 自动拼接代理前缀（按当前部署子路径动态推导，如 /wechatapph5/api）
30:         options.url = getApiPrefix() + options.url
31:       }
32:       else {
33:         options.url = baseUrl + options.url
34:       }
35:       // #endif
36:       // 非H5正常拼接
37:       // #ifndef H5
38:       options.url = baseUrl + options.url
39:       // #endif
40:       // TIPS: 如果需要对接多个后端服务，也可以在这里处理，拼接成所需要的地址
