// 判断当前是否处于 App 的真实入口页（首页为 pages/login）。
// 分享/深链会直接打开子页面路径，此时 URL 上的 token 不应被信任，避免会话被劫持。
function isEntryRoute(url) {
  try {
    const hashIndex = url.indexOf('#')
    const hashPart = hashIndex >= 0 ? url.slice(hashIndex + 1) : ''
    // hash 路由形如 #/pages/login?xxx；无 hash（history 模式或首页）也视为入口
    if (!hashPart || hashPart === '/') {
      return true
    }
    const routePath = hashPart.split('?')[0]
    return routePath === '/' || routePath === '/pages/login' || routePath === 'pages/login'
  } catch (e) {
    return true
  }
}

// 将 token / isphone 从地址栏 URL 中剥离（同时处理 # 前 query 与 # 后 query），
// 避免 token 停留在地址栏而被再次分享/复制，导致其他用户被登入他人账号。
function stripTokenFromUrl() {
  try {
    const url = window.location.href
    const hashIndex = url.indexOf('#')
    const beforeHash = hashIndex >= 0 ? url.slice(0, hashIndex) : url
    const hashPart = hashIndex >= 0 ? url.slice(hashIndex) : ''

    const stripParams = (q: string) => q
      .replace(/([?&])(token|isphone)=[^&#]*/g, '')
      // 清理因移除参数残留的 ? / &
      .replace(/^\?&/, '?')
      .replace(/[?&]$/, '')
      .replace(/&&/g, '&')

    const [beforePath, beforeQuery = ''] = beforeHash.split('?')
    const newBefore = beforeQuery ? `${beforePath}?${stripParams(beforeQuery)}` : beforePath

    let newHash = hashPart
    if (hashPart.includes('?')) {
      const [hashPath, hashQuery] = hashPart.split('?')
      newHash = `${hashPath}?${stripParams(hashQuery)}`
    }

    const newUrl = newBefore + newHash
    if (newUrl !== url) {
      window.history.replaceState(window.history.state, '', newUrl)
    }
  } catch (e) {
    // 剥离失败不影响主流程
  }
}

onLaunch((options) => {
